fun interface Policy {                     // SAM: each rule can be a lambda
    fun decide(ctx: SecurityContext, action: Action, resource: Resource): Boolean
}
fun <T> guard(policy: Policy, ctx: SecurityContext, action: Action,
              resource: Resource, block: () -> T): T {
    if (!policy.decide(ctx, action, resource)) throw AccessDeniedException()
    return block()                          // resource code stays rule-free
}
